/** localStorage key carrying the persisted flavour choice. */
export const FLAVOR_STORAGE_KEY = 'dsh.tokyonight.flavor'

/** localStorage key recording the last built-in theme preference. */
export const RESTORE_STORAGE_KEY = 'dsh.tokyonight.restore'

/** localStorage key carrying the auto-check update preference (item H). */
export const AUTO_CHECK_KEY = 'dsh.tokyonight.autoCheck'

/** localStorage key carrying the update channel preference (item I). */
export const UPDATE_CHANNEL_KEY = 'dsh.tokyonight.updateChannel'

/** localStorage key carrying the user token overrides JSON (item K). */
export const OVERRIDES_KEY = 'dsh.tokyonight.overrides'

/** localStorage key carrying the shiki style preference (item M). */
export const SHIKI_STYLE_KEY = 'dsh.tokyonight.shikiStyle'

/** localStorage key carrying the follow-the-OS flag (issue #36). */
export const FOLLOW_SYSTEM_KEY = 'dsh.tokyonight.followSystem'

/** localStorage key carrying the follow-mode dark half (issue #36). */
export const FOLLOW_DARK_KEY = 'dsh.tokyonight.followDark'

/** Accepted flavour values — the three registered theme ids plus `off`. These
 *  MUST stay in sync with the registered themes (guarded by
 *  tests/palettes.spec.ts) because the persisted value is the theme id. */
export const TOKYONIGHT_FLAVOR_VALUES = [
  ...TOKYONIGHT_FLAVORS.map((f) => f.themeId),
  'off',
] as const

/** `off` means: fall back to the official theme (default). */
export type FlavorChoice = (typeof TOKYONIGHT_FLAVOR_VALUES)[number]

/** The flavour whose themeId this is, or `off`. */
export function flavorFromThemeId(themeId: string): FlavorChoice {
  return TOKYONIGHT_FLAVORS.some((f) => f.themeId === themeId) ? themeId as FlavorChoice : 'off'
}

/** The flavour registered for a theme id, or undefined when not a TokyoNight theme. */
export function flavorInfo(themeId: string): TokyoNightFlavorInfo | undefined {
  return TOKYONIGHT_FLAVORS.find((f) => f.themeId === themeId)
}

/** Read the persisted flavour (absent / unknown values mean the default `off`). */
export function readFlavor(): FlavorChoice {
  try {
    const raw = localStorage.getItem(FLAVOR_STORAGE_KEY)
    return raw !== null && (TOKYONIGHT_FLAVOR_VALUES as readonly string[]).includes(raw)
      ? raw as FlavorChoice
      : 'off'
  } catch {
    return 'off'
  }
}

/** Whether localStorage carries an EXPLICIT `off` flavour choice.
 *
 * `readFlavor()` maps both "no value" and "off" to `off`, and the two are not
 * the same thing: an absent value only means THIS browser/origin never chose
 * (a first visit, cleared site data, or a second Desktop instance that landed
 * on the next free loopback port), while the durable store — which may
 * legitimately hold a flavour picked elsewhere — is machine-wide. Only a
 * literal `off` in storage proves the user (or another window) actually turned
 * the flavour off, which is the case the cross-tab restore must act on
 * (audit F4). */
export function readExplicitFlavorOff(): boolean {
  try {
    return localStorage.getItem(FLAVOR_STORAGE_KEY) === 'off'
  } catch {
    return false
  }
}

/** Persist the flavour choice (storage failures keep the in-memory state). */
export function writeFlavor(choice: FlavorChoice): void {
  try {
    localStorage.setItem(FLAVOR_STORAGE_KEY, choice)
  } catch {
    /* in-memory state still applies for this tab */
  }
}

/** Remember a built-in preference (system/light/dark) whenever the runtime is
 *  not on a TokyoNight flavour, so switching the plugin off restores the
 *  user's pre-plugin choice instead of dropping them onto 'system'. The boot
 *  preference is the settings-document value, so this survives Desktop's
 *  per-launch port churn without joining the durable state schema. */
export function rememberBuiltinPreference(preference: string): void {
  if ((TOKYONIGHT_FLAVOR_VALUES as readonly string[]).includes(preference)) return
  try {
    localStorage.setItem(RESTORE_STORAGE_KEY, preference)
  } catch {
    /* nothing to restore later — 'off' falls back to 'system' */
  }
}

/** The preference to restore when turning the flavour off (default: system). */
export function readRestoredPreference(): 'system' | 'light' | 'dark' {
  try {
    const raw = localStorage.getItem(RESTORE_STORAGE_KEY)
    return raw === 'light' || raw === 'dark' ? raw : 'system'
  } catch {
    return 'system'
  }
}

/** Read the persisted auto-check flag (absent means the shipped default: on). */
export function readAutoCheck(): boolean {
  try {
    const raw = localStorage.getItem(AUTO_CHECK_KEY)
    return raw === null ? DEFAULT_AUTO_CHECK : raw === 'true'
  } catch {
    return DEFAULT_AUTO_CHECK
  }
}

/** Persist the auto-check flag. */
export function writeAutoCheck(value: boolean): void {
  try {
    localStorage.setItem(AUTO_CHECK_KEY, String(value))
  } catch {
    /* in-memory state still applies */
  }
}

/** Read the persisted update channel (absent means `latest`). */
export function readUpdateChannel(): UpdateChannel {
  try {
    return localStorage.getItem(UPDATE_CHANNEL_KEY) === 'beta' ? 'beta' : DEFAULT_UPDATE_CHANNEL
  } catch {
    return DEFAULT_UPDATE_CHANNEL
  }
}

/** Persist the update channel. */
export function writeUpdateChannel(value: UpdateChannel): void {
  try {
    localStorage.setItem(UPDATE_CHANNEL_KEY, value)
  } catch {
    /* in-memory state still applies */
  }
}

/** Read the persisted token overrides (unparseable/absent → empty map).
 *
 * Sanitized on read (`sanitizeOverrides`, the same guard the settings document
 * goes through) so localStorage and the durable section always have the SAME
 * shape. Without it a key that is not a `--` token (e.g. `dsw-static-blue-500`
 * typed without the dashes) lives in localStorage only: the hydration compares
 * the two shapes, sees a difference, and "the document wins" overwrites the
 * entry — the user's row vanished a debounce-beat after it was typed. */
export function readOverrides(): Record<string, string> {
  try {
    const raw = localStorage.getItem(OVERRIDES_KEY)
    if (raw === null) return {}
    return sanitizeOverrides(JSON.parse(raw))
  } catch {
    return {}
  }
}

/** Persist the token overrides (storage failures keep the in-memory state). */
export function writeOverrides(value: Record<string, string>): void {
  try {
    localStorage.setItem(OVERRIDES_KEY, JSON.stringify(value))
  } catch {
    /* in-memory state still applies */
  }
}

let overridesSnapshotCache: Record<string, string> | null = null

/** Stable-reference snapshot of the token overrides for `useSyncExternalStore`.
 * `readOverrides()` parses localStorage and returns a NEW object per call —
 * a React store whose getSnapshot returns a fresh reference every time loops
 * forever ("Maximum update depth exceeded") and the settings row crashes.
 * This accessor returns the SAME object while the persisted map is unchanged
 * and swaps only when the content actually differs. */
export function overridesSnapshot(): Record<string, string> {
  const next = readOverrides()
  const cached = overridesSnapshotCache
  if (cached !== null && JSON.stringify(cached) === JSON.stringify(next)) return cached
  overridesSnapshotCache = next
  return next
}

/** Inert legacy value retained for settings-document round-tripping.
 * Rendering always uses SHIKI_TOKENS[flavor].default.
 */
export function readShikiStyle(): ShikiStyle {
  try {
    return localStorage.getItem(SHIKI_STYLE_KEY) === 'italic-comments' ? 'italic-comments' : DEFAULT_SHIKI_STYLE
  } catch {
    return DEFAULT_SHIKI_STYLE
  }
}

/** Persist the shiki style. */
export function writeShikiStyle(value: ShikiStyle): void {
  try {
    localStorage.setItem(SHIKI_STYLE_KEY, value)
  } catch {
    /* in-memory state still applies */
  }
}

/** Read the persisted follow-the-OS flag (issue #36; absent means off). */
export function readFollowSystem(): boolean {
  try {
    return localStorage.getItem(FOLLOW_SYSTEM_KEY) === 'true'
  } catch {
    return false
  }
}

/** Persist the follow-the-OS flag. */
export function writeFollowSystem(value: boolean): void {
  try {
    localStorage.setItem(FOLLOW_SYSTEM_KEY, String(value))
  } catch {
    /* in-memory state still applies */
  }
}

/** Read the follow-mode dark half (only the three dark flavours are legal). */
export function readFollowDark(): FollowDarkFlavor {
  try {
    const raw = localStorage.getItem(FOLLOW_DARK_KEY)
    return raw !== null && (FOLLOW_DARK_FLAVORS as readonly string[]).includes(raw)
      ? raw as FollowDarkFlavor
      : DEFAULT_FOLLOW_DARK
  } catch {
    return DEFAULT_FOLLOW_DARK
  }
}

/** Persist the follow-mode dark half. */
export function writeFollowDark(value: FollowDarkFlavor): void {
  try {
    localStorage.setItem(FOLLOW_DARK_KEY, value)
  } catch {
    /* in-memory state still applies */
  }
}

/**
 * Turn one ADOPTED durable section back into local state — the only place a
 * settings-document section is written into the localStorage cache.
 *
 * Issue #38 (2026-11-06): this used to be two hand-copied field lists inside
 * the adoption path, and #36 added `followSystem` / `followDark` to the section
 * without adding them to either. Two origins (Desktop `dsh-app://app` + a LAN
 * web client on another port) then adopted the document without caching the
 * pair, so every publish saw "local ≠ document" and pushed its own stale value
 * back — measured in production at ~0.8 `settings/mutate` per second,
 * ping-ponging `followDark` between two flavours and rewriting
 * `cordis.patch.yml` forever. The record below is a mapped type over the
 * section, so a field added to `TokyoNightSettingsSection` fails to compile
 * until it is cached here too (same drift class as `stateToMutateOps`, which
 * got a derived guard in issue #26).
 *
 * ⚠️ `glass` is written LAST on purpose. `applyRemote` republishes
 * synchronously (`sync()` → `theme/change` → the `glass.subscribe` hook) and
 * that publish runs `queuePersist`, which snapshots `buildLocalState()` on the
 * spot. Writing the glass material earlier — where the pre-#38 code had it,
 * right after the flavour — leaves the follow pair un-cached at snapshot time,
 * so the adoption arms `pendingLocalSection` with a section no flush can ever
 * settle; issue #31's guard 1 then swallows the NEXT external document edit.
 * Verified with a two-snapshot repro: appending the two writes at the END of
 * the adoption block stops the loop but still loses the following edit.
 *
 * @param section - the section the settings document resolved to.
 * @param glass - the glass layer; `applyRemote` caches the knobs and republishes.
 */
export function writeLocalSection(
  section: TokyoNightSettingsSection,
  glass: { applyRemote(state: TokyoNightSettingsSection['glass']): void },
): void {
  // `(value: never) => void` keeps the record free of variance friction while
  // still forcing EVERY key of the section to be present.
  const writers: { [K in keyof TokyoNightSettingsSection]: (value: never) => void } = {
    flavor: writeFlavor,
    followSystem: writeFollowSystem,
    followDark: writeFollowDark,
    autoCheck: writeAutoCheck,
    updateChannel: writeUpdateChannel,
    overrides: writeOverrides,
    shikiStyle: writeShikiStyle,
    // Last: it republishes, and that publish re-reads the whole cache.
    glass: (value) => glass.applyRemote(value),
  }
  for (const key of Object.keys(writers) as (keyof TokyoNightSettingsSection)[]) {
    // One assertion for the loop: the record is exhaustive by construction, but
    // TypeScript cannot correlate two indexes driven by the same union key.
    const write = writers[key] as (value: unknown) => void
    write(section[key])
  }
}

/**
 * Does this host ship the menu blur that makes a translucent menu surface work?
 *
 * `--dsw-specific-menu` only became translucent together with the blur: upstream
 * 0.1.7-alpha.1 changed it from `var(--dsw-alias-bg-layer-3)` to a literal
 * 58%/50% neutral AND introduced `--dsw-menu-backdrop-filter: blur(40px)
 * saturate(150%)` in the same release (checked against the 0.1.6-alpha.1 tag,
 * which still has the opaque ladder step and no blur token). On an older host —
 * `latest` is still the 0.1.5 line — the same fill would be *plain*
 * transparency: the transcript would show through the menu with nothing to
 * soften it, and the token also paints panels that carry text (queue dock, todo
 * panel, goal bar, job list, stat dialog, …).
 *
 * Read through <body>'s computed style, where ui-theme declares both tokens.
 * `--dsw-mask-blur` is probed first as a sanity check: it exists in every host
 * we support, so an empty read means the theme stylesheet is not in the cascade
 * yet (or the environment exposes no computed styles). Answering "false" then
 * is the safe side — the opaque fill is correct for every host that predates
 * the blur.
 */
export function hostHasMenuBlur(): boolean {
  if (typeof getComputedStyle !== 'function') return false
  const body = document.body
  if (body === null) return false
  const styles = getComputedStyle(body)
  if (styles.getPropertyValue('--dsw-mask-blur').trim() === '') return false
  return styles.getPropertyValue('--dsw-menu-backdrop-filter').trim() !== ''
}

/**
 * Token patch for `--dsw-specific-menu`: the flavour's translucent fill stands
 * where the host declares the matching blur (the value lives in palettes.ts),
 * and the opaque pre-0.1.7 ladder step is injected everywhere else. Applied
 * BEFORE the user overrides, so an explicit `--dsw-specific-menu` in the
 * overrides editor still wins.
 */
export function menuSurfaceFor(hostHasBlur: boolean): Record<string, string> {
  return hostHasBlur ? {} : { '--dsw-specific-menu': 'var(--dsw-alias-bg-layer-3)' }
}

/** Built-in preferences the Appearance row can explicitly pick. */
const BUILTIN_PREFERENCES = ['light', 'dark', 'system'] as const
type BuiltinPreference = (typeof BUILTIN_PREFERENCES)[number]

function isBuiltinPreference(value: string): value is BuiltinPreference {
  return (BUILTIN_PREFERENCES as readonly string[]).includes(value)
}

/** Whether an observed built-in preference wins over the persisted flavour.
 *  Only a light/dark value the user explicitly picked in THIS session — the
 *  recorded `liveBuiltinPick` from the setTheme wrapper — wins. Values adopted
 *  from the settings document at boot/reload (`livePick` null) never win
 *  (issue #6: a doc persisted as `ui-theme.preference: light` was mistaken for
 *  a user choice and buried the flavour on every refresh/restart), and
 *  "system" never wins: while a flavour is on, the TokyoNight row is the
 *  active controller and the Appearance row must not bury the persisted
 *  choice. A user's explicit light/dark pick still wins immediately (matching
 *  livePick) and choosing "off" in the TokyoNight row restores it. */
export function builtinPickWins(
  preference: string,
  livePick: BuiltinPreference | null,
): boolean {
  if (preference !== 'light' && preference !== 'dark') return false
  return preference === livePick
}

/** Required services: slots + locale (settings rows) and theme (register +
 *  switch). The durable settings transport is NOT a hard dependency: which
 *  service provides it depends on the host version (issue #15 — 0.1.7-alpha.1
 *  replaced `settingsScope` with `configForms`), so `createDurableScope`
 *  binds whichever one appears through its own optional injections. Listing
 *  either name here would leave the plugin permanently pending on the other
 *  half of the installed base. */
export const inject = ['slots', 'locale', 'theme']

/**
 * Register the TokyoNight dictionaries, the flavour themes (lazy — item JJ:
 * only the active flavour is registered, the rest on first selection), and
 * the settings rows.
 * @param ctx - client root context.
 */
export function apply(ctx: ClientContext): void {
  // Bilingual balance is enforced by the typed register call (zh + en);
  // ja/ko/es/fr/de ride the untyped language-pack form and are registered
  // as selectable languages (fallback chain → en) so the dictionaries are
  // reachable without an external language pack (item CC).
  //
  // Every call rides `tolerantRegistration` (issue #23): a peer language pack
  // (dsh-locale-pack, …) that already owns a BCP 47 id makes `addLanguage`
  // throw `locale "ja" is already registered`, and a raw throw here fails
  // THIS entry → the whole web boot aborts → the desktop's crash rescue
  // disables every third-party plugin. A skipped registration costs nothing:
  // our dictionaries still land (they register into our OWN namespace), and
  // the id collision only means the peer's language entry already stands.
  ctx.effect(() => {
    const disposers = [
      tolerantRegistration(() => ctx.locale.register(NS, { zh, en })),
      tolerantRegistration(() => ctx.locale.register(NS, 'ja', ja)),
      tolerantRegistration(() => ctx.locale.register(NS, 'ko', ko)),
      tolerantRegistration(() => ctx.locale.register(NS, 'es', es)),
      tolerantRegistration(() => ctx.locale.register(NS, 'fr', fr)),
      tolerantRegistration(() => ctx.locale.register(NS, 'de', de)),
      tolerantRegistration(() => ctx.locale.addLanguage({ id: 'ja', label: '日本語', fallback: 'en' })),
      tolerantRegistration(() => ctx.locale.addLanguage({ id: 'ko', label: '한국어', fallback: 'en' })),
      tolerantRegistration(() => ctx.locale.addLanguage({ id: 'es', label: 'Español', fallback: 'en' })),
      tolerantRegistration(() => ctx.locale.addLanguage({ id: 'fr', label: 'Français', fallback: 'en' })),
      tolerantRegistration(() => ctx.locale.addLanguage({ id: 'de', label: 'Deutsch', fallback: 'en' })),
    ]
    return () => {
      for (const dispose of disposers) dispose()
    }
  }, 'tokyonight: dictionaries')

  const theme = ctx.get('theme') as ThemeRuntime

  // Lazy theme registration (item JJ): at most the flavour currently in use
  // is registered; selecting a flavour registers it on demand and the fiber
  // disposer releases every registration. Overrides (item K) and the shiki
  // style (item M) are read at registration time, so a preference change
  // re-registers the active flavour with the merged tokens.
  const themeDisposers = new Map<string, () => void>()
  const registerThemeFor = (flavor: TokyoNightFlavorInfo): void => {
    if (themeDisposers.has(flavor.themeId)) return
    // Flavour id for the shiki token lookup: themeId is "tokyonight-light"
    // → key is "light".
    const flavorId = flavor.themeId.replace('tokyonight-', '') as TokyoNightFlavorId
    const shiki = SHIKI_TOKENS[flavorId].default
    // Tolerant (issue #23): `theme.register` throws `theme "…" is already
    // registered` when another instance of this plugin owns the id (a
    // duplicate install). One reachable path runs it synchronously
    // (applyScopeSnapshot → reapplyThemePrefs, inside the boot effect), so a
    // raw throw could fail the entry; the others (the deferred restore
    // microtask, the storage event) would turn into uncaught errors. A skip
    // is right either way: the theme exists (the peer's copy), `setTheme`
    // below still works, and the no-op disposer memoizes the skip so we do
    // not re-attempt on every override change.
    const disposer = tolerantRegistration(() => theme.register({
      id: flavor.themeId,
      colorScheme: flavor.colorScheme,
      tokens: {
        ...flavor.tokens,
        ...shiki,
        // Host-shape patch (0.1.7 vs the 0.1.5 latest line): keep the menu
        // surface readable on hosts without the menu blur. Below the user
        // overrides on purpose — see menuSurfaceFor().
        ...menuSurfaceFor(hostHasMenuBlur()),
        ...readOverrides(),
      } as ThemeTokens,
    }))
    themeDisposers.set(flavor.themeId, disposer)
  }
  const ensureThemeRegistered = (themeId: string): void => {
    const flavor = flavorInfo(themeId)
    if (flavor !== undefined) registerThemeFor(flavor)
  }
  const disposeThemeRegistrations = (): void => {
    for (const dispose of themeDisposers.values()) dispose()
    themeDisposers.clear()
  }
  ctx.effect(() => disposeThemeRegistrations, 'tokyonight: flavour theme disposers')

  // The glass layer: a toggleable glassmorphism skin on top of the TokyoNight
  // themes. It owns its lifecycle (enable flag + knobs persist in
  // localStorage as the in-browser cache; the durable copy is the settings
  // document hydrated/pushed below; every effect is released with this fiber).
  // It is created before the boot-restore effect so hydration can overlay the
  // persisted glass state onto the layer.
  const glass = new GlassLayer(ctx)

  // The official settings transport for the TokyoNight durable state. Which
  // seam it is depends on the host version (0.1.7-alpha.1 replaced the
  // `settingsScope` namespace binding with the `configForms` entry form), so
  // the facade picks whichever service the host provides and never blocks
  // this fiber on it. The document is the source of truth; the scope derives
  // from the shared mirror and never blocks on the transport.
  const scope = createDurableScope(ctx)

  // The current durable snapshot: flavour from the localStorage cache (the
  // authoritative write target of the settings row) plus the glass layer's
  // remote state and the preference fields. Passed to the debounced scope
  // persist by reference so the flush always captures the freshest values.
  const buildLocalState = (): TokyoNightState => ({
    version: STATE_VERSION,
    // `FlavorChoice` widens to `string` (palettes carry `themeId: string`), but
    // the runtime value is always one of the three theme ids or `off` — the
    // same set as `FlavorValue`, guarded by tests/state.spec.ts.
    flavor: readFlavor() as FlavorValue,
    // Issue #36 — re-sanitized on the way out so the two stores can never
    // disagree about the "follow ⇒ flavor !== off" invariant.
    followSystem: readFollowSystem() && readFlavor() !== 'off',
    followDark: readFollowDark(),
    glass: glass.getRemoteState(),
    autoCheck: readAutoCheck(),
    updateChannel: readUpdateChannel(),
    overrides: readOverrides(),
    shikiStyle: readShikiStyle(),
  })

  // Preference pub/sub: the settings rows read/write autoCheck, channel,
  // overrides and shikiStyle through localStorage; any change re-renders the
  // rows (emitPrefs) and the conflict counter feeds the update row's
  // "另一窗口已更新" banner (item X).
  const prefsListeners = new Set<() => void>()
  const emitPrefs = (): void => {
    for (const listener of prefsListeners) listener()
  }
  let conflictCount = 0
  const conflictListeners = new Set<() => void>()
  const emitConflict = (): void => {
    conflictCount += 1
    for (const listener of conflictListeners) listener()
  }

  // ── Follow the OS scheme (issue #36) ──────────────────────────────────────
  //
  // A registered theme carries ONE `colorScheme`, so "Light on light, Night on
  // dark" cannot be expressed as a theme id. What CAN express it is a token
  // override layer: `theme.overrideTokens(source, { token: { light, dark } })`
  // is folded by `composeActive()` against the ACTIVE (OS-resolved) scheme, so
  // as long as the preference stays `system` the media listener keeps firing,
  // `data-ds-theme-source` keeps publishing `system`, and the shell mirrors
  // that into `nativeTheme.themeSource` — native chrome follows too.
  //
  // The whole mechanism therefore has one hard precondition: while follow mode
  // is on, the runtime preference MUST be `system` and NO flavour theme is
  // active (see `applyDesired`'s follow branch and `docs/issue-36-follow-system.md`).
  const FOLLOW_LAYER_SOURCE = PACKAGE_NAME
  /** Disposer of the currently stacked follow layer (`undefined` = no layer). */
  let followLayerDispose: (() => void) | undefined
  /** Content signature of the stacked layer, so a no-op refresh does not
   *  republish (every `overrideTokens` call emits `theme/change`). */
  let followLayerSignature: string | undefined

  /** Theme-id → shiki/flavour key ("tokyonight-light" → "light"). */
  const flavorKey = (flavor: TokyoNightFlavorInfo): TokyoNightFlavorId =>
    flavor.themeId.replace('tokyonight-', '') as TokyoNightFlavorId

  /** Whether this host serves `overrideTokens` at all. Hosts before that API
   *  cannot follow the OS; the row hides the control instead of offering a
   *  switch that would do nothing. */
  const followSupported = (): boolean =>
    typeof (theme as unknown as { overrideTokens?: unknown }).overrideTokens === 'function'

  /** Follow mode is wanted AND possible. `off` always wins: turning the plugin
   *  off must not leave a layer painting TokyoNight tokens. */
  const followWanted = (): boolean =>
    followSupported() && readFollowSystem() && readFlavor() !== 'off'

  /**
   * The two halves of the follow layer.
   *
   * Precedence per token mirrors `registerThemeFor`: flavour tokens < shiki <
   * host-shape menu patch < user overrides (later wins). A user override is
   * scheme-agnostic by contract, so the SAME value goes into both halves.
   * A token present in only one flavour falls back to the other half's value so
   * every entry stays a well-formed `{ light, dark }` pair (`overrideTokens`
   * throws on a bare string).
   * @returns the layer, or null when a flavour table is missing.
   */
  const followLayerTokens = (): ThemeTokenOverrides | null => {
    const light = flavorInfo(FOLLOW_LIGHT_FLAVOR)
    const dark = flavorInfo(readFollowDark())
    if (light === undefined || dark === undefined) return null
    const lightShiki = SHIKI_TOKENS[flavorKey(light)].default as Record<string, string>
    const darkShiki = SHIKI_TOKENS[flavorKey(dark)].default as Record<string, string>
    const menu = menuSurfaceFor(hostHasMenuBlur())
    const overrides = readOverrides()
    const names = new Set([
      ...Object.keys(light.tokens),
      ...Object.keys(dark.tokens),
      ...Object.keys(lightShiki),
      ...Object.keys(darkShiki),
      ...Object.keys(menu),
      ...Object.keys(overrides),
    ])
    const pairs: ThemeTokenOverrides = {}
    for (const name of names) {
      const lightValue = overrides[name] ?? menu[name] ?? lightShiki[name] ?? light.tokens[name]
      const darkValue = overrides[name] ?? menu[name] ?? darkShiki[name] ?? dark.tokens[name]
      if (lightValue === undefined && darkValue === undefined) continue
      pairs[name] = { light: lightValue ?? darkValue as string, dark: darkValue ?? lightValue as string }
    }
    return pairs
  }

  /** Remove the follow layer (idempotent). */
  const disposeFollowLayer = (): void => {
    if (followLayerDispose === undefined) return
    followLayerDispose()
    followLayerDispose = undefined
    followLayerSignature = undefined
  }

  /**
   * Stack (or refresh, or retire) the follow layer.
   *
   * MUST be called outside a `theme/change` dispatch: `overrideTokens`
   * publishes, and a synchronous publish from inside a dispatch lets the
   * presenter apply the OUTER (stale) snapshot last — the issue #10 trap, same
   * reason `scheduleRestore` defers.
   */
  const syncFollowLayer = (): void => {
    if (!followWanted()) {
      disposeFollowLayer()
      return
    }
    const tokens = followLayerTokens()
    if (tokens === null) {
      disposeFollowLayer()
      return
    }
    const signature = JSON.stringify(tokens)
    if (followLayerDispose !== undefined && signature === followLayerSignature) return
    const dispose = theme.overrideTokens(FOLLOW_LAYER_SOURCE, tokens)
    // The old disposer is a documented no-op once the same source has been
    // re-overridden; calling it keeps the bookkeeping honest for hosts that
    // hand out fresh sources.
    followLayerDispose?.()
    followLayerDispose = dispose
    followLayerSignature = signature
  }

  // Re-register the active flavour after an override/shiki-style change so
  // the new token mix applies (the disposed registration is replaced by one
  // carrying the merged overrides).
  //
  // Issue #31: this used to dispose EVERY registration and then re-register the
  // active one. The ThemeRuntime's disposer resets `preference` to its default
  // when the disposed theme is the ACTIVE one ("Disposing the theme backing the
  // active preference resets the preference to the default", ui-theme
  // `register()`), so the whole UI dropped to the official theme and only a
  // deferred microtask brought the flavour back — one dropped microtask and the
  // user's flavour was gone while the row still showed it. Now only the active
  // flavour is recycled, and the preference is put back in the SAME synchronous
  // block, so no observer can read the intermediate `system`.
  const reapplyThemePrefs = (): void => {
    // Issue #36: in follow mode the runtime preference is `system` and no
    // flavour theme is registered-active, so the recycle below would early
    // return and a shiki/override change would never reach the screen. The
    // layer is what carries the tokens there — re-stack it instead.
    if (followWanted()) {
      syncFollowLayer()
      return
    }
    disposeFollowLayer()
    const active = theme.getTheme().preference
    const flavor = flavorInfo(active)
    if (flavor === undefined) return
    const dispose = themeDisposers.get(flavor.themeId)
    if (dispose === undefined) return
    themeDisposers.delete(flavor.themeId)
    dispose()
    registerThemeFor(flavor)
    try {
      // Re-assert synchronously: `dispose()` above already published a snapshot
      // whose preference is the default.
      theme.setTheme(flavor.themeId)
    } catch {
      /* unregistered — the deferred restore below retries on the next event */
    }
  }

  // Debounced push of the current local state into the settings document.
  // When the scope is not usable (memory mode / absent transport) the write
  // is skipped entirely — localStorage stays the only store, exactly the
  // pre-0.5.0 route-missing fallback. The write is read-side guarded (item
  // C/X): a flush whose base revision the document moved past returns
  // `stale`, the local change is abandoned, and the remote state is
  // re-adopted + surfaced in the update row.
  let lastWrittenSection: TokyoNightSettingsSection | undefined
  let handleStaleConflict: (() => void) | undefined
  // Issue #31: the un-recording setTheme entry point (see `commitTheme`),
  // published by the restore effect for the `off` paths that live outside it.
  let applyRestoredPreference: ((id: string) => void) | undefined
  // R2 (2026-10-10 review): whether a local change was made while the durable
  // scope was NOT yet usable — the boot window, when the settings service
  // lands late or its first snapshot is still in flight. Such a change has no
  // channel to be pushed through yet, and the FIRST snapshot the scope later
  // resolves may describe an OLDER document — without this flag the hydration
  // below would "adopt the document" and silently roll the change back. The
  // flag makes the first usable snapshot push the local state instead; a
  // section that already equals the local state makes the queued write a
  // noop, so the ordinary boot path pays nothing.
  let pendingLocalPush = false
  // Issue #31 (echo race, 2026-10-27): the local section as of the newest change
  // this window made and has NOT yet committed, or null when there is nothing
  // owed. It is ARMED on the same predicate as `pendingLocalPush` (local moved
  // away from `syncedSection`) and DISARMED when a flush settles — the read
  // side needs it because a snapshot may arrive while a change is still sitting
  // in the debounce queue or on the wire, carrying the document as it was
  // BEFORE that change. Adopting such a snapshot silently reverts the user's
  // pick (measured on the live desktop shell: a flavour click was overwritten
  // 1.4 s later by `applyScopeSnapshot`, and the queued flush then persisted the
  // reverted value). `pendingLocalPush` covers only the window where the scope
  // is not usable yet; this one covers the ordinary, usable-scope case.
  let pendingLocalSection: TokyoNightSettingsSection | null = null
  // Issue #31, second guard: the highest namespace revision this window has
  // seen. A snapshot that reports a LOWER revision is a stale view (a describe
  // read that resolved late, a superseded write's answer), never a newer
  // document, so it must not be adopted. `revisionKind` resets the high-water
  // mark when the durable channel is re-bound (the two seams number their
  // revisions independently).
  let maxSeenRevision: number | undefined
  let revisionKind: string | undefined
  // Issue #31: the last document section this window actually accepted. A queued
  // flush whose local section already equals it is not "a change the document
  // does not hold yet", so it must not arm `pendingLocalSection` — the adoption
  // path itself re-publishes through the glass layer, and arming on that
  // self-inflicted publish would block the NEXT external edit for a whole
  // debounce beat.
  let lastDocumentSection: TokyoNightSettingsSection | null = null

  // Issue #30: the local section as of the last moment this window knew it was
  // IN SYNC with the durable document — boot, or the last adoption / successful
  // write below. `pendingLocalPush` is armed only when the local state has
  // actually moved away from this baseline, and the replay carries only the
  // moved fields: on a fresh origin (empty localStorage) the "local state" is
  // nothing but the shipped defaults, and replaying it whole rewrote the
  // document to `flavor: off` / `glass: off` / `mica`.
  let syncedSection = settingsSectionFromState(buildLocalState())
  // The revision the pending write is based on, captured when the change is
  // SCHEDULED (audit F2): reading it at flush time made the read-side staleness
  // guard compare a revision with itself — both reads sit in one synchronous
  // block — so `'stale'` was unreachable and an external edit inside the
  // debounce window was silently overwritten. One capture per burst.
  const baseRevisionTracker = createBaseRevisionTracker()
  const queuePersist = (): void => {
    // Marked at SCHEDULE time, not at flush time: the dangerous window is
    // "change happened before the scope first became usable", which includes
    // the debounce beat BEFORE the flush runs (a scope that turns ready
    // inside that beat would hydrate and roll the change back before the
    // flush ever sees it).
    //
    // Issue #30: armed only on a REAL change. The boot path queues persists on
    // its own — the glass layer republishes on every `theme/change` (ui-theme
    // adopts its preference at boot) and on `sync()` — and on a fresh origin
    // none of those carries a user choice. Arming on them was the bug: the
    // first usable snapshot then replayed the shipped defaults over the
    // document. The comparison only runs while the scope is unusable, so the
    // hot path (a slider drag) pays nothing.
    //
    // Issue #31: the same "did a real change happen?" predicate also arms
    // `pendingLocalSection`, which the adoption guard below reads — so it is
    // computed once and shared.
    const localSection = settingsSectionFromState(buildLocalState())
    const pendingVsDocument = lastDocumentSection === null
      || !settingsSectionsEqual(localSection, lastDocumentSection)
    if (pendingVsDocument && !settingsSectionsEqual(localSection, syncedSection)) {
      pendingLocalSection = localSection
      if (!isScopeUsable(scope.getSnapshot())) pendingLocalPush = true
    }
    baseRevisionTracker.capture(() => scope.getSnapshot().revision)
    scheduleDurablePersist(persistLocal)
  }
  const persistLocal = (): void => {
    // Consume the base first: a bail-out (unusable scope) must not leave it
    // behind for the next burst.
    const baseRevision = baseRevisionTracker.take()
    const snapshot = scope.getSnapshot()
    if (!isScopeUsable(snapshot)) {
      // Nothing can be pushed, so localStorage is the only store again and the
      // pending intent must not keep blocking adoption (see `pendingLocalSection`).
      pendingLocalSection = null
      return
    }
    const state = buildLocalState()
    const flushed = settingsSectionFromState(state)
    void persistStateToScope(scope, state, { baseRevision, lastWrittenSection }).then((outcome) => {
      // Only disarm the intent this flush actually carried: a newer change may
      // have re-armed it while the write was on the wire, and THAT one still
      // owes a write.
      const settled = pendingLocalSection !== null && settingsSectionsEqual(pendingLocalSection, flushed)
      if (outcome === 'written') {
        lastWrittenSection = flushed
        // The local cache and the document agree again — a new sync point.
        syncedSection = flushed
        if (settled) pendingLocalSection = null
      } else if (outcome === 'noop') {
        // The document already equals the local state (the normal echo of our
        // own committed write), so this is a sync point too — without moving the
        // baseline here a later adoption would compare against a stale one.
        syncedSection = flushed
        if (settled) pendingLocalSection = null
      } else if (outcome === 'stale') {
        // The document moved past us and the movement is NOT our own echo, so
        // the local change is abandoned: the intent must stop guarding the
        // adoption below, or the conflict path could never adopt.
        if (settled) pendingLocalSection = null
        emitConflict()
        handleStaleConflict?.()
      }
      // 'error' (transport failure / refused mutation) keeps the intent armed on
      // purpose: the choice is still newer than the document and the next flush
      // retries it. Adopting on a failed write is exactly the silent revert this
      // guard exists to stop.
    })
  }

  /** How long the Host's pre-paint palette may survive before it is removed
   *  unconditionally (issue #30 补充). Generous on purpose: removing it EARLY
   *  re-exposes the official palette for one frame, which is the bug. */
  const BOOT_PALETTE_FALLBACK_MS = 10_000

  // Restore the persisted choice and defend it against the built-in
  // Appearance scope's `adopt()`. Two stores feed the desired flavour:
  // localStorage (the in-browser cache — instant at boot and the cross-tab
  // `storage` bus) and the durable store (the source of truth — required
  // because localStorage is per-browser and per-origin while the DSH home is
  // machine-wide; see `src/state.ts`).
  //
  // The re-assert is not a fixed boot window. The built-in ThemeRuntime's
  // `adopt()` re-applies the settings-document preference on every settings
  // reload — and switching the model always reloads the settings document —
  // writing "system" when `ui-theme.preference` was never written, or the
  // persisted light/dark when the document holds one. adopt() writes the
  // runtime preference directly and bypasses setTheme, so the setTheme wrapper
  // below is the one seam that tells explicit picks apart: we restore our
  // flavour whenever the runtime preference is NOT a built-in value the user
  // clicked in the Appearance row THIS session, and choosing "off" in the
  // TokyoNight row clears the persisted flavour before the switch so this
  // guard does not fight it.
  ctx.effect(() => {
    // Session-live record of the user's last EXPLICIT built-in pick, kept by
    // the setTheme wrapper below. The wrapper is the only seam that
    // distinguishes "the user clicked light/dark/system in the Appearance
    // row" from "ThemeRuntime.adopt() copied the settings document's value
    // at boot/reload" — adopt() writes the preference directly and never goes
    // through setTheme, so a doc-adopted light/dark leaves this null and the
    // guard below cannot mistake it for a user choice. Picking a TokyoNight
    // flavour (or the wrapper's own flavour restore) clears the record.
    let liveBuiltinPick: BuiltinPreference | null = null
    // Issue #30 补充: last-resort removal of the Host's pre-paint palette. Its
    // `html body` selector outranks the official `body` block, so a sheet left
    // behind would pin every token and defeat later theme switches — it must
    // never outlive the boot interval even if every other removal point is
    // skipped (an unknown host shape, a restore that never runs).
    const bootPaletteFallback = window.setTimeout(() => { clearBootPalette() }, BOOT_PALETTE_FALLBACK_MS)
    const originalSetTheme = theme.setTheme
    // Issue #31: an internal restore is NOT an explicit pick. It used to go
    // through the wrapper below, which recorded `liveBuiltinPick` — so a restore
    // to `dark` made the plugin believe the user had clicked dark in the
    // Appearance row THIS session, and `builtinPickWins()` then refused every
    // later flavour restore (turn the flavour off, another window turns it back
    // on ⇒ this window never follows). Only a call from OUTSIDE (the Appearance
    // row) records now.
    const commitTheme = (id: string, record: boolean): void => {
      if (record) liveBuiltinPick = isBuiltinPreference(id) ? id : null
      originalSetTheme.call(theme, id)
      // Issue #30 补充: the ThemePresenter applies the new tokens inside the
      // call above, so the pre-paint sheet is spent by the time it returns —
      // and a built-in pick means a flavour sheet must not survive at all.
      clearBootPalette()
    }
    // Named on purpose (R1, 2026-10-10 review): the cleanup below may only
    // restore the original while the method is still OUR wrapper. Another
    // extension replacing it afterwards owns the slot by then, and an
    // unconditional write-back of the original would silently unhook it.
    const restoreGuardSetTheme = (id: string): void => { commitTheme(id, true) }
    theme.setTheme = restoreGuardSetTheme
    // The `off` / cross-window paths live outside this effect; they need the
    // un-recording entry point.
    applyRestoredPreference = (id: string) => { commitTheme(id, false) }

    // Issue #36: the deferred follow-mode half of `applyDesired`, deferred for
    // the same two reasons `scheduleRestore` is: (a) switching the preference
    // must not publish from inside a `theme/change` dispatch (issue #10 — the
    // presenter would apply the OUTER, stale snapshot last), and (b) stacking
    // the layer publishes as well (`overrideTokens` emits), so it needs the
    // same protection.
    let followSyncPending = false
    const scheduleFollowSync = (): void => {
      if (followSyncPending) return
      followSyncPending = true
      queueMicrotask(() => {
        followSyncPending = false
        // Re-read at run time: a newer intent (follow turned off, another
        // window's pick) may have landed while this sat in the queue.
        if (!followWanted()) {
          disposeFollowLayer()
          return
        }
        syncFollowLayer()
        const preference = theme.getTheme().preference
        if (preference === 'system') {
          // The layer now paints the palette; the pre-paint sheet (#30 补充)
          // must retire or it keeps pinning every token through `html body`.
          clearBootPalette()
          return
        }
        // An explicit Appearance pick THIS session still wins — the same rule
        // the flavour restore follows (`builtinPickWins`). Follow mode stays
        // persisted and re-asserts on the next boot/reload instead of fighting
        // the click: writing a durable field from a `theme/change` listener is
        // exactly the issue #31 echo shape.
        if (builtinPickWins(preference, liveBuiltinPick)) return
        try {
          commitTheme('system', false)
        } catch {
          /* keep the current theme; the next event retries */
        }
      })
    }

    // Issue #10: a synchronous setTheme inside a theme/change dispatch
    // re-enters publish() — the ThemePresenter (registered after us) then
    // applies the STALE snapshot carried by the OUTER dispatch last, so the
    // DOM ends up dark/system while the runtime preference is the flavour.
    // Defer the restore out of the current dispatch (microtask) and re-check
    // at run time, so the flavour's setTheme is always the LAST event the
    // presenter sees. A single in-flight restore coalesces repeated
    // observations (boot, adopt() reloads, storage echoes).
    let restorePending = false
    // Issue #31: the LATEST desired value of the burst, not the first one. The
    // old coalescing dropped every later observation (`if (restorePending)
    // return`), so two different intents inside one task left the stale one
    // applied — and with no further theme/change to correct it.
    let pendingDesired: string | undefined
    // `desired` is widened to string on purpose: the SAME deferred path also
    // carries the built-in restore (audit F4) — when the persisted choice went
    // 'off' somewhere else, the theme to apply is a built-in preference
    // (`system`/`light`/`dark`), not a flavour id.
    const scheduleRestore = (desired: string): void => {
      pendingDesired = desired
      if (restorePending) return
      restorePending = true
      queueMicrotask(() => {
        restorePending = false
        const wanted = pendingDesired as string
        pendingDesired = undefined
        const preference = theme.getTheme().preference
        if (preference === wanted) {
          // The flavour is ALREADY the active theme — no setTheme will run, so
          // this is the only chance to retire the pre-paint sheet (issue #30
          // 补充). Nothing is painted between here and the presenter's own
          // work, so removing it cannot flash.
          clearBootPalette()
          return
        }
        // Re-check the guard at run time: a newer explicit built-in pick
        // (or a newer event) still wins over the persisted flavour.
        if (builtinPickWins(preference, liveBuiltinPick)) return
        // Lazy registration (item JJ): the theme must exist before setTheme.
        ensureThemeRegistered(wanted)
        try {
          // Records nothing (issue #31): a restore is not a user pick.
          commitTheme(wanted, false)
        } catch {
          // Theme not registered yet — a later theme/change re-runs applyDesired.
        }
      })
    }

    const applyDesired = (): void => {
      // Record the built-in preference on every non-flavour observation (boot,
      // adopt() reloads, explicit Appearance changes) BEFORE any re-assert, so
      // 'off' below can hand the user back exactly what they had.
      //
      // Issue #36: NOT while follow mode owns the runtime. The preference is
      // `system` there by our own doing, and recording it would clobber the
      // user's real light/dark — which is precisely what "off" has to restore.
      const follow = followWanted()
      if (!follow) rememberBuiltinPreference(theme.getTheme().preference)
      const desired = readFlavor()
      if (follow) {
        // The layer carries the palette and the preference must stay `system`;
        // every branch below is about a FLAVOUR preference that must not exist
        // right now, so none of them applies.
        scheduleFollowSync()
        return
      }
      if (followLayerDispose !== undefined) {
        // Follow mode just ended (this row, another window, or the settings
        // document). Retire the layer on the deferred path — disposing
        // publishes too.
        scheduleFollowSync()
      }
      if (desired === 'off') {
        // The persisted choice is off — but this session may still be rendering
        // a TokyoNight flavour (another window or the settings document turned
        // it off). Hand the user back their built-in preference, exactly like
        // the row's own `select('off')` path. Gated on an EXPLICIT 'off' in
        // localStorage (audit F4): an empty storage may just mean this
        // browser/origin never chose, so the absence of a value is NOT a choice
        // and the durable store — which may legitimately restore a flavour — is
        // authoritative. Without that gate we would fight the document on every
        // boot of a fresh origin.
        const preference = theme.getTheme().preference
        if (readExplicitFlavorOff()) {
          // An explicit 'off' means no flavour is wanted, so a sheet injected
          // for one (this page may have been rendered while the document still
          // held a flavour) must go — otherwise it would pin every token.
          clearBootPalette()
          if (flavorFromThemeId(preference) !== 'off') scheduleRestore(readRestoredPreference())
        }
        return
      }
      const preference = theme.getTheme().preference
      if (preference === desired) {
        // Already rendering this flavour — retire the pre-paint sheet (see the
        // same case in scheduleRestore).
        clearBootPalette()
        return
      }
      // A built-in preference only wins if the user explicitly picked it in
      // THIS session (matching liveBuiltinPick). "system" and boot/adopt()
      // values adopted from the settings document (liveBuiltinPick null) are
      // stale for the plugin — the TokyoNight row choice is newer than the
      // document's light/dark, so restore the flavour then.
      if (builtinPickWins(preference, liveBuiltinPick)) return
      scheduleRestore(desired)
    }
    applyDesired()
    const disposer = ctx.on('theme/change', applyDesired)
    const onStorage = (event: StorageEvent): void => {
      // Issue #36: another window toggled follow mode or its dark half. The
      // layer has to be rebuilt here — the flavour path below would call
      // setTheme and kill the `system` preference follow depends on.
      if (event.key === FOLLOW_SYSTEM_KEY || event.key === FOLLOW_DARK_KEY) {
        emitPrefs()
        applyDesired()
        return
      }
      if (event.key !== FLAVOR_STORAGE_KEY) return
      // Issue #36: while follow mode is on, a flavour change from another
      // window only alters the LAYER's dark half; the preference must stay
      // `system` or the OS listener dies.
      if (followWanted()) {
        emitPrefs()
        applyDesired()
        return
      }
      const next = readFlavor()
      if (next !== 'off') {
        ensureThemeRegistered(next)
        try {
          theme.setTheme(next)
        } catch {
          /* unknown persisted value — keep the current theme */
        }
        return
      }
      // Another window turned the flavour off (audit F4): this tab must land on
      // the built-in preference too, or it keeps rendering TokyoNight while the
      // persisted choice — and the settings row of the other window — say off.
      if (flavorFromThemeId(theme.getTheme().preference) === 'off') return
      try {
        // Not an Appearance pick (issue #31), so it must not be recorded.
        commitTheme(readRestoredPreference(), false)
      } catch {
        /* keep the current theme rather than dropping the user into nothing */
      }
    }
    window.addEventListener('storage', onStorage)

    // Any glass change (enable flag or knob) coalesces into one durable write.
    // Issue #30: only when a PERSISTED field actually moved. The layer also
    // republishes on `theme/change` (Appearance switch, `ui-theme` adopt() at
    // boot) where nothing durable changed — those publishes used to queue a
    // pointless flush that could land as a false "another window changed it".
    const offGlass = glass.subscribe(() => {
      queuePersist()
    })

    // Hydrate the durable source of truth without blocking paint. The scope
    // derives from the shared settings mirror (no wire read of its own), so
    // this is sync once the mirror has resolved; if it arrives later, the
    // subscription below catches it — the localStorage fast path keeps
    // working in the meantime.
    //
    // The hydration is echo-safe: the Host folds our own committed writes
    // back into the mirror, and when the echoed section equals the local
    // state (the normal case after a change we just persisted) we skip the
    // write-back. A section that differs is an external edit (another
    // surface, a hand-edited document, a reload) — the document wins.
    const applyScopeSnapshot = (): void => {
      const snapshot = scope.getSnapshot()
      const state = durableStateFromSnapshot(snapshot)
      if (state === null) return // loading / memory / absent — localStorage-only
      // Issue #31, guard 2: revision monotonicity. Writes only ever move the
      // namespace revision forward, so a snapshot reporting an OLDER revision is
      // a stale view (a describe read that resolved late, a superseded write's
      // answer folded after a newer one) — adopting it rewinds the document the
      // user is looking at.
      const revision = snapshot.revision
      if (revision !== undefined) {
        if (revisionKind !== scope.kind) {
          revisionKind = scope.kind
          maxSeenRevision = undefined
        }
        if (maxSeenRevision !== undefined && revision < maxSeenRevision) return
        maxSeenRevision = Math.max(maxSeenRevision ?? revision, revision)
      }
      const local = buildLocalState()
      // R2: a change made before the scope first became usable wins over the
      // first usable snapshot (see `pendingLocalPush`) — but only the FIELDS
      // that actually moved since the last sync point (issue #30). A whole
      // state replay from a fresh origin carries nothing but the shipped
      // defaults and wiped the document.
      if (pendingLocalPush) {
        pendingLocalPush = false
        const replayed = replayLocalChanges(state, syncedSection, settingsSectionFromState(local))
        if (replayed.changed) {
          // The boot-window change is newer than the document: adopt the
          // MERGED state into the local cache, then let the debounced flush
          // carry it out (`persistLocal` rebuilds from the cache, so it writes
          // exactly these values).
          // Issue #38: ONE writer for the whole section (glass last), so the
          // follow pair can never be dropped from this list again.
          writeLocalSection(replayed.state, glass)
          emitPrefs()
          reapplyThemePrefs()
          applyDesired()
          syncedSection = settingsSectionFromState(replayed.state)
          // The snapshot still describes the OLDER document this replay just
          // beat, so the queued push below must stay armed (issue #31).
          lastDocumentSection = settingsSectionFromState(state)
          queuePersist()
          return
        }
        // Nothing of ours moved (the ordinary fresh-origin boot publish) —
        // fall through to the adoption path below, exactly as if the flag had
        // never been armed.
      }
      // The channel owns the "does the document hold a user layer yet?" test:
      // the new form's `user` is an empty object until someone writes, while
      // the legacy document omits it entirely.
      if (!scope.hasUserLayer(snapshot)) {
        // No user layer in the document yet: this session's localStorage
        // choice is newer than the shipped defaults the document resolves
        // to, so push it into the document (the upgrade path for a
        // localStorage-only session predating the settings migration).
        if (!isDefaultState(local)) queuePersist()
        return
      }
      // A document holding unpersistable override entries (a hand-edited key
      // that is not a `--` token) can never compare equal to the sanitized
      // local shape, so every publish would re-run this adoption forever.
      // Adopt, then push the cleaned map back once so the document converges
      // (audit F7). The push is queued AFTER the adoption below, because the
      // adoption cancels the queued flush (issue #31).
      const pushCleaned = hasUnpersistableOverrides((snapshot.value as { overrides?: unknown } | undefined)?.overrides)
      // A document the user wrote wins over the local cache, but echoes of
      // our own committed writes are skipped (they equal the local state).
      const localSection = settingsSectionFromState(local)
      const documentSection = settingsSectionFromState(state)
      if (settingsSectionsEqual(localSection, documentSection)) {
        // Our own echo. Recording the section is what keeps `queuePersist` from
        // arming a pending intent for it (issue #31).
        lastDocumentSection = documentSection
        return
      }
      // Issue #31, guard 1 (THE measured bug): this window has a change the
      // document does not hold yet — it is sitting in the debounce queue or on
      // the wire. The snapshot therefore describes the document as it was
      // BEFORE that change, and adopting it silently reverts the user's pick
      // (and the queued flush then persists the reverted value, so the loss
      // becomes durable). Keep the local state; the flush carries it out.
      if (pendingLocalSection !== null && !settingsSectionsEqual(pendingLocalSection, documentSection)) return
      // Committing to the document: the queued flush would now only write the
      // pre-adoption state back, so drop it (and the revision it captured — a
      // stale base would be read as a conflict by the next burst). Both sync
      // points move BEFORE the writes below, because `writeLocalSection` ends
      // on `glass.applyRemote` and that republishes, which runs `queuePersist`
      // (issue #31).
      cancelDurablePersist()
      baseRevisionTracker.take()
      pendingLocalSection = null
      lastDocumentSection = documentSection
      syncedSection = documentSection
      // Issue #38: the follow pair rides this call too — the pre-fix list
      // omitted it, and that omission is what kept two origins ping-ponging.
      writeLocalSection(state, glass)
      emitPrefs()
      reapplyThemePrefs()
      applyDesired()
      // `syncedSection` / `lastDocumentSection` were already moved onto the
      // document above (before the writes), so the boot replay below compares
      // against the fresh baseline.
      if (pushCleaned) queuePersist()
    }
    applyScopeSnapshot()
    const offScope = scope.subscribe(applyScopeSnapshot)

    handleStaleConflict = () => applyScopeSnapshot()

    return () => {
      offScope()
      offGlass()
      disposer()
      window.removeEventListener('storage', onStorage)
      window.clearTimeout(bootPaletteFallback)
      // A stopped plugin must not leave the sheet pinned over the official
      // theme (issue #30 补充).
      clearBootPalette()
      cancelDurablePersist()
      handleStaleConflict = undefined
      applyRestoredPreference = undefined
      // Undo the setTheme wrapper so a stopped plugin leaves the runtime as
      // it found it — but only while the wrapper is still ours (R1): if
      // another extension replaced it after us, that replacement is the
      // current owner and force-writing the original back would unhook it
      // without a trace.
      if (theme.setTheme === restoreGuardSetTheme) {
        theme.setTheme = originalSetTheme
      } else {
        console.warn('[dsh-tokyonight] theme.setTheme was replaced by another extension; leaving it in place')
      }
    }
  }, 'tokyonight: theme restore')

  const injected = (): TokyoNightRowInjected => ({
    themes: TOKYONIGHT_FLAVORS.map((flavor) => ({
      id: flavor.themeId,
      label: flavor.label,
      accent: flavor.accent,
    })),
    current: () => {
      // Issue #36: in follow mode the runtime preference is `system` (no
      // flavour is active), so the highlighted cube has to come from the
      // persisted choice — it is exactly what the UI would fall back to if
      // follow were switched off.
      if (readFollowSystem() && readFlavor() !== 'off') return readFlavor()
      const pref = theme.getTheme().preference
      return flavorFromThemeId(pref)
    },
    subscribe: (listener) => ctx.on('theme/change', listener),
    followAvailable: followSupported(),
    followSystem: () => readFollowSystem(),
    setFollowSystem: (enabled: boolean) => {
      if (!followSupported()) return
      if (enabled) {
        // Follow mode is a MODIFIER on a TokyoNight choice, never a way to
        // paint TokyoNight over `off` — adopt the dark half when nothing is
        // selected yet.
        if (readFlavor() === 'off') writeFlavor(readFollowDark())
        writeFollowSystem(true)
        // Layer first, preference second, one synchronous block: the composed
        // tokens must already be in place when the `system` switch publishes,
        // or the presenter paints the official palette for one frame.
        syncFollowLayer()
        try {
          if (applyRestoredPreference !== undefined) applyRestoredPreference('system')
          else theme.setTheme('system')
        } catch {
          /* keep the current theme rather than dropping the user into nothing */
        }
      } else {
        writeFollowSystem(false)
        disposeFollowLayer()
        const target = readFlavor()
        if (target !== 'off') {
          try {
            if (applyRestoredPreference !== undefined) applyRestoredPreference(target)
            else theme.setTheme(target)
          } catch {
            /* keep the current theme; the restore guard retries on next event */
          }
        }
      }
      emitPrefs()
      queuePersist()
    },
    followDark: () => readFollowDark(),
    setFollowDark: (dark: FollowDarkFlavor) => {
      if (!(FOLLOW_DARK_FLAVORS as readonly string[]).includes(dark)) return
      writeFollowDark(dark)
      // Outside a dispatch (a row click), so the re-stack may publish directly.
      if (followWanted()) syncFollowLayer()
      emitPrefs()
      queuePersist()
    },
    select: (choice: FlavorChoice) => {
      // Issue #36: picking a flavour (or turning the plugin off) is an explicit
      // statement about the FIXED flavour, so it ends follow mode. Persist that
      // BEFORE any setTheme: the restore guard and `applyDesired` read the
      // settled state, and a stale `followSystem: true` would drag the runtime
      // back to `system` a microtask later.
      if (readFollowSystem()) {
        writeFollowSystem(false)
        disposeFollowLayer()
      }
      if (choice === 'off') {
        // Restore the built-in preference the user had before the flavour
        // ('system' when nothing was recorded). Persist the abandoned choice
        // BEFORE setTheme: setTheme emits theme/change synchronously, so the
        // restore guard must already read `off` here and not re-assert the
        // previous flavour.
        writeFlavor('off')
        // Wrapped like every other setTheme call (issue #23 audit): a throw
        // here used to escape into the row's click handler; keep the current
        // theme instead of dropping the user into nothing. Issue #31: goes
        // through the UN-recording entry point — turning the flavour off is not
        // an Appearance pick, and recording it would veto every later restore.
        try {
          if (applyRestoredPreference !== undefined) applyRestoredPreference(readRestoredPreference())
          else theme.setTheme(readRestoredPreference())
        } catch {
          /* keep the current theme rather than dropping the user into nothing */
        }
        queuePersist()
        return
      }
      const flavor = flavorInfo(choice)
      if (!flavor) return
      // Persist first so the restore guard (a theme/change listener) sees the
      // new flavour when setTheme below emits synchronously. Lazy
      // registration: the theme must exist before setTheme (item JJ).
      const previous = readFlavor()
      writeFlavor(flavor.themeId)
      ensureThemeRegistered(flavor.themeId)
      // Issue #31: a throw here used to be swallowed, leaving the cache on the
      // NEW flavour and the runtime on the OLD one — "I clicked it and nothing
      // happened", with no retry and no notice. Retry once after forgetting the
      // registration memo (a tolerated duplicate skip or a recycled
      // registration can leave the memo pointing at a dead registrant), and if
      // it still fails put the cache back so the two stores never disagree.
      try {
        theme.setTheme(flavor.themeId)
      } catch {
        themeDisposers.get(flavor.themeId)?.()
        themeDisposers.delete(flavor.themeId)
        registerThemeFor(flavor)
        try {
          theme.setTheme(flavor.themeId)
        } catch {
          writeFlavor(previous)
          emitPrefs()
          emitConflict()
          return
        }
      }
      queuePersist()
    },
    overrides: overridesSnapshot,
    setOverrides: (overrides: Record<string, string>) => {
      writeOverrides(overrides)
      emitPrefs()
      reapplyThemePrefs()
      queuePersist()
    },
    subscribePrefs: (listener: () => void) => {
      prefsListeners.add(listener)
      return () => { prefsListeners.delete(listener) }
    },
  })

  // Every row registration rides `tolerantRegistration` (issue #23): the
  // callback runs SYNCHRONOUSLY when the slot is already declared (the
  // renderer's documented contract), so a duplicate id at the same priority
  // (`list slot "…" already has an entry with id "…"`, e.g. a duplicate
  // install) would otherwise throw straight through apply() and fail the
  // boot. A skipped row costs nothing: the occupant is the same row.
  const glassInjected = (): GlassRowInjected => ({
    getState: () => glass.getSnapshot(),
    subscribe: (listener) => glass.subscribe(listener),
    setEnabled: (enabled) => { glass.setEnabled(enabled) },
    setMode: (mode) => { glass.setMode(mode) },
    setBlur: (blur) => { glass.setBlur(blur) },
    setFrost: (frost) => { glass.setFrost(frost) },
    setBrightness: (brightness) => { glass.setBrightness(brightness) },
    setGap: (gap) => { glass.setGap(gap) },
    setGlow: (glow) => { glass.setGlow(glow) },
    setGlowStrength: (glowStrength) => { glass.setGlowStrength(glowStrength) },
    setGlowSize: (glowSize) => { glass.setGlowSize(glowSize) },
    resetDefaults: () => { glass.resetDefaults() },
  })

  // Update check: the Host owns the npm lookup (Node fetch, no CORS); the row
  // only fetches the same-origin route and renders the verdict. Upgrade stays
  // a terminal action — the row just surfaces the CLI command.
  // The plugin's OWN settings page (issue #27). One nav entry, and every
  // preference row lives on it instead of being spliced into General. Two
  // contracts, both load-bearing:
  //  - `tolerantRegistration`: with the slot already declared the callback runs
  //    SYNCHRONOUSLY, so a duplicate install (same section id) would otherwise
  //    throw straight through apply() and fail the boot (issue #23 / AGENTS.md
  //    rule 5). A skipped registration costs nothing: the occupant is the same
  //    page.
  //  - `label` is a THUNK: the shell resolves it on every read, so switching the
  //    interface language re-renders the nav row without re-registering.
  // `order: 25` keeps the official sections (account -10 / general 0 /
  // models 10 / plugins 15 / agent-presets 20) ahead of ours.
  const t = ctx.locale.bind(NS)
  const sectionInjected = (): TokyoNightSettingsPageInjected => ({
    flavor: injected(),
    glass: glassInjected(),
  })

  ctx.slots.inject('settings.section', () => tolerantRegistration(() => ctx.slots.register({
    name: 'settings.section',
    id: 'tokyonight',
    order: 25,
    label: () => t('nav.title'),
    locale: NS,
    inject: sectionInjected,
  }, TokyoNightSettingsPage)))
  // Plugins-page card: the settings section on this plugin's OWN detail page in
  // the Plugin manager (DSH >= 0.2.0-rc.2). Three things about this
  // registration are contracts, not style (see `src/client/detail-card.tsx`):
  //  - `key` is the BUNDLE PACKAGE NAME, because the page dispatches with
  //    `{ entryKey: pkg.name }` — NOT `TOKYONIGHT_ENTRY_ID`, which keys the
  //    settings namespace;
  //  - the section exists only while this registration does, so `whileServed`
  //    withdraws it with the namespace instead of leaving an empty block;
  //  - the face is the SAME three factories the General rows use, so the second
  //    home shares the durable section rather than a copy of it.
  // `whileServed` is guarded because not every host past 0.1.7 serves it, and
  // `slots.inject` waits for the slot's DECLARATION — a host without the Plugin
  // manager never fires it (no throw, no pending state).
  const detailInjected = (): TokyoNightDetailCardInjected => ({
    flavor: injected(),
    glass: glassInjected(),
  })

  ctx.inject(['configForms'], (formsCtx) => {
    const forms = formsCtx.configForms
    if (typeof forms.whileServed !== 'function') return
    return forms.whileServed([TOKYONIGHT_ENTRY_ID], () => ctx.slots.inject(
      'plugins.bundle.config',
      () => tolerantRegistration(() => ctx.slots.register({
        name: 'plugins.bundle.config',
        key: PACKAGE_NAME,
        locale: NS,
        inject: detailInjected,
      }, TokyoNightDetailCard)),
    ))
  })
}